function method strength(extension: string) : int
{
    var cap := CountUppercase(extension);
    var sm := CountLowercase(extension);
    return cap - sm;
}

function CountUppercase(s: string) : int
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= count <= i
        invariant i <= s.Length
    {
        if Char.IsUpper(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function CountLowercase(s: string) : int
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= count <= i
        invariant i <= s.Length
    {
        if Char.IsLower(s[i]) {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}
